  1778	M3Result  Compile_Operator  (IM3Compilation o, m3opcode_t i_opcode)
  1779	{
  1780	    M3Result result;
  1781	
  1782	    const M3OpInfo * op = GetOpInfo(i_opcode);
  1783	
  1784	    IM3Operation operation;
  1785	
  1786	    // This preserve is for for FP compare operations.
  1787	    // either need additional slot destination operations or the
  1788	    // easy fix, move _r0 out of the way.
  1789	    // moving out the way might be the optimal solution most often?
  1790	    // otherwise, the _r0 reg can get buried down in the stack
  1791	    // and be idle & wasted for a moment.
  1792	    if (IsFpType (GetStackTopType (o)) and IsIntType (op->type))
  1793	    {
  1794	_       (PreserveRegisterIfOccupied (o, op->type));
  1795	    }
  1796	
  1797	    if (op->stackOffset == 0)
  1798	    {
  1799	        if (IsStackTopInRegister (o))
  1800	        {
  1801	            operation = op->operations [0]; // _s
  1802	        }
  1803	        else
  1804	        {
  1805	_           (PreserveRegisterIfOccupied (o, op->type));
  1806	            operation = op->operations [1]; // _r
  1807	        }
  1808	    }
  1809	    else
  1810	    {
  1811	        if (IsStackTopInRegister (o))
  1812	        {
  1813	            operation = op->operations [0];  // _rs
  1814	
  1815	            if (IsStackTopMinus1InRegister (o))
  1816	            {                                       d_m3Assert (i_opcode == 0x38 or i_opcode == 0x39);
  1817	                operation = op->operations [3]; // _rr for fp.store
  1818	            }
  1819	        }
  1820	        else if (IsStackTopMinus1InRegister (o))
  1821	        {
  1822	            operation = op->operations [1]; // _sr
  1823	
  1824	            if (not operation)  // must be commutative, then
  1825	                operation = op->operations [0];
  1826	        }
  1827	        else
  1828	        {
  1829	_           (PreserveRegisterIfOccupied (o, op->type));     // _ss
  1830	            operation = op->operations [2];
  1831	        }
  1832	    }
  1833	
  1834	    if (operation)
  1835	    {
  1836	_       (EmitOp (o, operation));
  1837	
  1838	_       (EmitTopSlotAndPop (o));
  1839	
  1840	        if (op->stackOffset < 0)
  1841	_           (EmitTopSlotAndPop (o));
  1842	
  1843	        if (op->type != c_m3Type_none)
  1844	_           (PushRegister (o, op->type));
  1845	    }
  1846	    else
  1847	    {
  1848	#       ifdef DEBUG
  1849	            result = ErrorCompile ("no operation found for opcode", o, "'%s'", op->name);
  1850	#       else
  1851	            result = ErrorCompile ("no operation found for opcode", o, "");
  1852	#       endif
  1853	        _throw (result);
  1854	    }
  1855	
  1856	    _catch: return result;
  1857	}
