  1860	M3Result  Compile_Convert  (IM3Compilation o, m3opcode_t i_opcode)
  1861	{
  1862	    M3Result result = m3Err_none;
  1863	
  1864	    const M3OpInfo * opInfo = GetOpInfo(i_opcode);
  1865	
  1866	    bool destInSlot = IsRegisterTypeAllocated (o, opInfo->type);
  1867	    bool sourceInSlot = IsStackTopInSlot (o);
  1868	
  1869	    IM3Operation op = opInfo->operations [destInSlot * 2 + sourceInSlot];
  1870	
  1871	_   (EmitOp (o, op));
  1872	_   (EmitTopSlotAndPop (o));
